INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Zentralelemente > Festplatten
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Festplatten unabhängig von der Schnittstelle des Mainboards ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "SATA oder NVMe müssen kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Anschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl von Festplatten immer die Speicherkapazitätsanforderungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Kapazität entscheidet über Nutzbarkeit"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Geschwindigkeit einer Festplatte irrelevant für die Systemleistung?', 2, '[{"text": "Nein", "correct": true, "because": "Schnellere Zugriffe verbessern Performance"}, {"text": "Ja", "correct": false, "because": "Geschwindigkeit beeinflusst System"}]'),
('00000000-0000-0000-0000-000000000000', 'Können HDDs und SSDs ohne Rücksicht auf die Stromversorgung kombiniert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Netzteil muss Leistung bereitstellen"}, {"text": "Ja", "correct": false, "because": "Strombedarf ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Festplatten mit größerer Kapazität immer schneller als solche mit kleinerer Kapazität?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt von Technologie ab"}, {"text": "Ja", "correct": false, "because": "Kapazität ≠ Geschwindigkeit"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Auswahl einer Festplatte am wichtigsten?', 3, '[{"text": "Anwendungsanforderungen", "correct": true, "because": "Bestimmen Kapazität und Geschwindigkeit"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Festplattentechnologie bietet die höchste Zugriffsgeschwindigkeit?', 2, '[{"text": "NVMe SSD", "correct": true, "because": "Nutzt PCIe für maximale Geschwindigkeit"}, {"text": "SATA SSD", "correct": false, "because": "Schneller als HDD, langsamer als NVMe"}, {"text": "HDD", "correct": false, "because": "Mechanisch, langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird für moderne interne Festplatten am häufigsten verwendet?', 2, '[{"text": "SATA", "correct": true, "because": "Standard für HDDs und SSDs"}, {"text": "USB", "correct": false, "because": "Extern, nicht intern"}, {"text": "IDE", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptaufgabe einer Festplatte im System?', 3, '[{"text": "Dauerhafte Datenspeicherung", "correct": true, "because": "Speichert Daten langfristig"}, {"text": "Datenverarbeitung", "correct": false, "because": "Aufgabe des Prozessors"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Nicht ihre Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit wird zur Messung der Festplattenkapazität verwendet?', 2, '[{"text": "Terabyte (TB)", "correct": true, "because": "Standard für große Kapazitäten"}, {"text": "Megahertz (MHz)", "correct": false, "because": "Geschwindigkeit, nicht Kapazität"}, {"text": "Watt (W)", "correct": false, "because": "Leistungsaufnahme"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Auswahl einer Festplatte?', 4, '[{"text": "Speicherkapazität", "correct": true, "because": "Definiert Speicherplatz"}, {"text": "Zugriffsgeschwindigkeit", "correct": true, "because": "Beeinflusst Performance"}, {"text": "Schnittstelle", "correct": true, "because": "Bestimmt Kompatibilität"}, {"text": "Gewicht der Festplatte", "correct": false, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine SSD gegenüber einer HDD?', 3, '[{"text": "Höhere Geschwindigkeit", "correct": true, "because": "Keine mechanischen Teile"}, {"text": "Geringerer Stromverbrauch", "correct": true, "because": "Effizienter Betrieb"}, {"text": "Größere Robustheit", "correct": true, "because": "Keine beweglichen Teile"}, {"text": "Geringere Kosten", "correct": false, "because": "SSDs sind teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl von Festplatten auftreten?', 3, '[{"text": "Inkompatibilität mit Mainboard", "correct": true, "because": "Falsche Schnittstelle"}, {"text": "Unzureichende Kapazität", "correct": true, "because": "Speicher reicht nicht"}, {"text": "Zu hoher Stromverbrauch", "correct": true, "because": "Netzteil überlastet"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Festplatte zukunftssicher?', 4, '[{"text": "Hohe Kapazität", "correct": true, "because": "Für wachsende Datenmengen"}, {"text": "NVMe-Unterstützung", "correct": true, "because": "Moderne Schnittstelle"}, {"text": "Hohe Geschwindigkeit", "correct": true, "because": "Für schnelle Zugriffe"}, {"text": "Integrierte Kühlung", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren besonders von schnellen Festplatten?', 3, '[{"text": "Datenbanken", "correct": true, "because": "Schnelle Zugriffe nötig"}, {"text": "Spiele", "correct": true, "because": "Kürzere Ladezeiten"}, {"text": "Betriebssystem", "correct": true, "because": "Schnellerer Start"}, {"text": "Textverarbeitung", "correct": false, "because": "Geringer Speicherbedarf"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) SSDs sind schneller als HDDs. b) Alle Festplatten verwenden dieselbe Schnittstelle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSDs ja, Schnittstellen variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NVMe-Festplatten nutzen PCIe für hohe Geschwindigkeit. b) HDDs sind robuster als SSDs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NVMe ja, SSDs robuster"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Festplattenkapazität wird in Terabyte gemessen. b) Geschwindigkeit ist für Backup-Festplatten irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TB ja, Geschwindigkeit auch bei Backup relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) SATA ist die gängigste Schnittstelle für Festplatten. b) SSDs verbrauchen mehr Strom als HDDs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SATA ja, SSDs effizienter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Festplatten beeinflussen die Systemstartzeit. b) Kapazität hat keinen Einfluss auf die Geschwindigkeit.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Startzeit ja, Kapazität unabhängig"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]');

